import { Menu, withStaticProperties } from 'tamagui'
import { createMenuParts } from './menuParts'
import type { DropdownMenuProps, DropdownMenuTriggerProps } from './types'

// Web: Tamagui's menu (WAI-ARIA menu pattern, keyboard + type-ahead).
// iOS / Android: see DropdownMenu.native.tsx (bottom sheet).

const parts = createMenuParts(Menu)

function DropdownMenuRoot({
  children,
  side = 'bottom',
  align = 'start',
  ...props
}: DropdownMenuProps) {
  const placement = align === 'center' ? side : (`${side}-${align}` as const)
  return (
    <Menu placement={placement} offset={4} allowFlip stayInFrame={{ padding: 8 }} {...props}>
      {children}
    </Menu>
  )
}

function DropdownMenuTrigger({ children }: DropdownMenuTriggerProps) {
  return <Menu.Trigger asChild>{children}</Menu.Trigger>
}

/**
 * A list of actions or options opened from a button. Keyboard and type-ahead
 * navigation on web; a bottom sheet on iOS and Android.
 */
export const DropdownMenu = withStaticProperties(DropdownMenuRoot, {
  Trigger: DropdownMenuTrigger,
  ...parts,
})

export type {
  DropdownMenuCheckboxItemProps,
  DropdownMenuContentProps,
  DropdownMenuGroupProps,
  DropdownMenuItemProps,
  DropdownMenuLabelProps,
  DropdownMenuProps,
  DropdownMenuRadioGroupProps,
  DropdownMenuRadioItemProps,
  DropdownMenuTriggerProps,
} from './types'

import { type ReactElement, cloneElement } from 'react'
import { withStaticProperties } from 'tamagui'
import { sheetMenu, useSheetMenu } from './sheetMenu'
import type { DropdownMenuTriggerProps } from './types'

// iOS / Android: a bottom sheet of large rows (see sheetMenu.tsx).

const { Root, ...parts } = sheetMenu

type PressableChild = ReactElement<{
  onPress?: (event: unknown) => void
  'aria-haspopup'?: string
  'aria-expanded'?: boolean
}>

function DropdownMenuTrigger({ children }: DropdownMenuTriggerProps) {
  const { open, setOpen } = useSheetMenu()
  const child = children as PressableChild
  return cloneElement(child, {
    'aria-haspopup': 'menu',
    'aria-expanded': open,
    onPress: (event: unknown) => {
      child.props.onPress?.(event)
      setOpen(!open)
    },
  })
}

export const DropdownMenu = withStaticProperties(Root, {
  Trigger: DropdownMenuTrigger,
  ...parts,
})

export type {
  DropdownMenuCheckboxItemProps,
  DropdownMenuContentProps,
  DropdownMenuGroupProps,
  DropdownMenuItemProps,
  DropdownMenuLabelProps,
  DropdownMenuProps,
  DropdownMenuRadioGroupProps,
  DropdownMenuRadioItemProps,
  DropdownMenuTriggerProps,
} from './types'

import { CheckIcon, IconDefaults } from '@advui/icons'
import { shadows, zIndex } from '@advui/theme'
import type { ReactNode } from 'react'
import { type Menu, View } from 'tamagui'
import { useReducedMotion } from '../../hooks/useReducedMotion'
import { Text } from '../typography/Text'
import {
  type DropdownMenuCheckboxItemProps,
  type DropdownMenuContentProps,
  type DropdownMenuGroupProps,
  type DropdownMenuItemProps,
  type DropdownMenuLabelProps,
  type DropdownMenuRadioGroupProps,
  type DropdownMenuRadioItemProps,
  textOf,
} from './types'

// Web menu surface and items, shared by Dropdown Menu and Context Menu. Each
// wraps its own Tamagui primitive (they use separate contexts) with the same
// parts API, so the parts are built once per primitive.

const itemFrame = {
  unstyled: true,
  flexDirection: 'row',
  alignItems: 'center',
  gap: '$2',
  minHeight: '$8',
  paddingHorizontal: '$2',
  borderRadius: '$sm',
  cursor: 'pointer',
  // Pointer movement focuses items, so one style covers mouse and keyboard.
  focusStyle: { backgroundColor: '$accent' },
  pressStyle: { backgroundColor: '$accentHover' },
  focusVisibleStyle: { outlineWidth: 0 },
  // Finger-sized rows on touch screens.
  $touchable: { minHeight: '$11' },
} as const

const disabledFrame = { opacity: 0.5, cursor: 'not-allowed' } as const

export function createMenuParts(Primitive: typeof Menu) {
  function ItemBody({
    children,
    icon,
    shortcut,
    destructive,
    leading,
  }: Pick<DropdownMenuItemProps, 'children' | 'icon' | 'shortcut' | 'destructive'> & {
    leading?: ReactNode
  }) {
    const color = destructive ? '$errorSoftForeground' : '$popoverForeground'
    return (
      <>
        {leading}
        {icon ? (
          <IconDefaults size={16} color={destructive ? color : '$mutedForeground'}>
            {icon}
          </IconDefaults>
        ) : null}
        <Primitive.ItemTitle
          unstyled
          flex={1}
          fontFamily="$body"
          fontSize="$2"
          lineHeight="$2"
          color={color}
        >
          {children}
        </Primitive.ItemTitle>
        {shortcut ? (
          <Text
            size="xs"
            tone="muted"
            letterSpacing={0.5}
            aria-hidden
            $touchable={{ display: 'none' }}
          >
            {shortcut}
          </Text>
        ) : null}
      </>
    )
  }

  function Content({ children, minWidth = '$48' }: DropdownMenuContentProps) {
    const reducedMotion = useReducedMotion()
    return (
      <Primitive.Portal zIndex={zIndex.popover}>
        <Primitive.Content
          unstyled
          backgroundColor="$popover"
          borderWidth={1}
          borderColor="$border"
          borderRadius="$lg"
          padding="$1"
          minWidth={minWidth}
          {...shadows.md}
          enterStyle={{ opacity: 0, scale: 0.97, y: -4 }}
          exitStyle={{ opacity: 0, scale: 0.97, y: -4 }}
          opacity={1}
          scale={1}
          y={0}
          transition={reducedMotion ? null : 'quicker'}
          animateOnly={['transform', 'opacity']}
        >
          {children}
        </Primitive.Content>
      </Primitive.Portal>
    )
  }

  function Item({
    children,
    icon,
    shortcut,
    destructive,
    disabled,
    onSelect,
    textValue,
  }: DropdownMenuItemProps) {
    return (
      <Primitive.Item
        {...itemFrame}
        {...(disabled ? disabledFrame : null)}
        disabled={disabled}
        onSelect={() => onSelect?.()}
        textValue={textOf(children, textValue)}
      >
        <ItemBody icon={icon} shortcut={shortcut} destructive={destructive}>
          {children}
        </ItemBody>
      </Primitive.Item>
    )
  }

  /** Fixed-width slot so checked and unchecked items line up. */
  function IndicatorSlot({ children }: { children: ReactNode }) {
    return (
      <View width="$4" alignItems="center" justifyContent="center">
        <Primitive.ItemIndicator unstyled>{children}</Primitive.ItemIndicator>
      </View>
    )
  }

  function CheckboxItem({
    children,
    checked = false,
    onCheckedChange,
    icon,
    shortcut,
    disabled,
    textValue,
  }: DropdownMenuCheckboxItemProps) {
    return (
      <Primitive.CheckboxItem
        {...itemFrame}
        {...(disabled ? disabledFrame : null)}
        checked={checked}
        onCheckedChange={(next) => onCheckedChange?.(next === true)}
        disabled={disabled}
        textValue={textOf(children, textValue)}
      >
        <ItemBody
          icon={icon}
          shortcut={shortcut}
          leading={
            <IndicatorSlot>
              <CheckIcon size={14} color="$popoverForeground" />
            </IndicatorSlot>
          }
        >
          {children}
        </ItemBody>
      </Primitive.CheckboxItem>
    )
  }

  function RadioGroup({ children, value, onValueChange }: DropdownMenuRadioGroupProps) {
    return (
      <Primitive.RadioGroup value={value} onValueChange={onValueChange}>
        {children}
      </Primitive.RadioGroup>
    )
  }

  function RadioItem({
    children,
    value,
    icon,
    shortcut,
    disabled,
    textValue,
  }: DropdownMenuRadioItemProps) {
    return (
      <Primitive.RadioItem
        {...itemFrame}
        {...(disabled ? disabledFrame : null)}
        value={value}
        disabled={disabled}
        textValue={textOf(children, textValue)}
      >
        <ItemBody
          icon={icon}
          shortcut={shortcut}
          leading={
            <IndicatorSlot>
              <View
                width="$2"
                height="$2"
                borderRadius="$full"
                backgroundColor="$popoverForeground"
              />
            </IndicatorSlot>
          }
        >
          {children}
        </ItemBody>
      </Primitive.RadioItem>
    )
  }

  function Label({ children }: DropdownMenuLabelProps) {
    return (
      <Primitive.Label
        unstyled
        paddingHorizontal="$2"
        paddingVertical="$1.5"
        fontFamily="$body"
        fontSize="$1"
        lineHeight="$1"
        fontWeight="600"
        color="$mutedForeground"
      >
        {children}
      </Primitive.Label>
    )
  }

  function Separator() {
    return (
      <Primitive.Separator
        unstyled
        height={1}
        backgroundColor="$border"
        marginVertical="$1"
        marginHorizontal="$-1"
      />
    )
  }

  function Group({ children }: DropdownMenuGroupProps) {
    return <Primitive.Group>{children}</Primitive.Group>
  }

  return { Content, Item, CheckboxItem, RadioGroup, RadioItem, Label, Separator, Group }
}

import { CheckIcon, IconDefaults } from '@advui/icons'
import { type ReactNode, createContext, useContext } from 'react'
import { Sheet, View } from 'tamagui'
import { useBackToClose } from '../../hooks/useBackToClose'
import { useControllableState } from '../../hooks/useControllableState'
import { useReducedMotion } from '../../hooks/useReducedMotion'
import { useRipple } from '../../hooks/useRipple'
import { Text } from '../typography/Text'
import type {
  DropdownMenuCheckboxItemProps,
  DropdownMenuContentProps,
  DropdownMenuGroupProps,
  DropdownMenuItemProps,
  DropdownMenuLabelProps,
  DropdownMenuProps,
  DropdownMenuRadioGroupProps,
  DropdownMenuRadioItemProps,
} from './types'

// iOS / Android menu, shared by Dropdown Menu and Context Menu (their
// `.native.tsx` files add the trigger). Native menus need a native module (not
// available in Expo Go), so the menu opens as a bottom sheet of large,
// labelled rows instead.

type MenuState = { open: boolean; setOpen: (open: boolean) => void }
const MenuContext = createContext<MenuState | null>(null)
const RadioContext = createContext<Pick<DropdownMenuRadioGroupProps, 'value' | 'onValueChange'>>({})

export function useSheetMenu() {
  const menu = useContext(MenuContext)
  if (!menu) throw new Error('Menu parts must be rendered inside their menu (e.g. <DropdownMenu>).')
  return menu
}

// `side` and `align` place the web menu; the sheet ignores them.
function Root({ children, open: openProp, defaultOpen = false, onOpenChange }: DropdownMenuProps) {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  // Android: the back button closes the sheet instead of leaving the screen.
  useBackToClose(open, () => setOpen(false))
  return <MenuContext.Provider value={{ open, setOpen }}>{children}</MenuContext.Provider>
}

function Content({ children }: DropdownMenuContentProps) {
  const menu = useSheetMenu()
  const { open, setOpen } = menu
  const reducedMotion = useReducedMotion()
  return (
    <Sheet
      open={open}
      onOpenChange={setOpen}
      modal
      dismissOnSnapToBottom
      snapPointsMode="fit"
      transition={reducedMotion ? undefined : 'medium'}
    >
      <Sheet.Overlay
        backgroundColor="$overlay"
        enterStyle={{ opacity: 0 }}
        exitStyle={{ opacity: 0 }}
        transition={reducedMotion ? undefined : 'quick'}
      />
      <Sheet.Handle backgroundColor="$borderStrong" />
      <Sheet.Frame
        backgroundColor="$popover"
        borderTopLeftRadius="$dialog"
        borderTopRightRadius="$dialog"
        paddingHorizontal="$2"
        paddingTop="$2"
        paddingBottom="$8"
      >
        <Sheet.ScrollView>
          {/* The sheet renders in a portal, which does not carry React context. */}
          <MenuContext.Provider value={menu}>
            {/* The sheet stays mounted while closed; hide its rows from screen
                readers until it opens, and keep VoiceOver inside while open. */}
            <View role="menu" aria-hidden={!open || undefined} accessibilityViewIsModal={open}>
              {children}
            </View>
          </MenuContext.Provider>
        </Sheet.ScrollView>
      </Sheet.Frame>
    </Sheet>
  )
}

function Row({
  role,
  checked,
  disabled,
  onPress,
  children,
}: {
  role: 'menuitem' | 'checkbox' | 'radio'
  checked?: boolean
  disabled?: boolean
  onPress: () => void
  children: ReactNode
}) {
  const ripple = useRipple({ color: '$popoverForeground', disabled })
  return (
    <View
      role={role}
      accessible
      aria-checked={role === 'menuitem' ? undefined : checked}
      aria-disabled={disabled || undefined}
      flexDirection="row"
      alignItems="center"
      gap="$3"
      minHeight="$12"
      paddingHorizontal="$3"
      borderRadius="$md"
      opacity={disabled ? 0.5 : 1}
      pressStyle={disabled || ripple.active ? undefined : { backgroundColor: '$accent' }}
      onPress={disabled ? undefined : onPress}
      // VoiceOver / TalkBack double-tap sends "activate"; a plain onPress on a
      // non-button view is not guaranteed to receive it.
      accessibilityActions={[{ name: 'activate' }]}
      onAccessibilityAction={(event: { nativeEvent: { actionName: string } }) => {
        if (!disabled && event.nativeEvent.actionName === 'activate') onPress()
      }}
      {...ripple.props}
    >
      {ripple.element}
      {children}
    </View>
  )
}

function Title({ children, destructive }: { children: ReactNode; destructive?: boolean }) {
  return (
    <Text flex={1} color={destructive ? '$errorSoftForeground' : '$popoverForeground'}>
      {children}
    </Text>
  )
}

function Icon({ icon, destructive }: { icon?: ReactNode; destructive?: boolean }) {
  if (!icon) return null
  return (
    <IconDefaults size={20} color={destructive ? '$errorSoftForeground' : '$mutedForeground'}>
      {icon}
    </IconDefaults>
  )
}

function Item({ children, icon, destructive, disabled, onSelect }: DropdownMenuItemProps) {
  const { setOpen } = useSheetMenu()
  return (
    <Row
      role="menuitem"
      disabled={disabled}
      onPress={() => {
        onSelect?.()
        setOpen(false)
      }}
    >
      <Icon icon={icon} destructive={destructive} />
      <Title destructive={destructive}>{children}</Title>
    </Row>
  )
}

function Indicator({ visible, children }: { visible: boolean; children: ReactNode }) {
  return (
    <View width="$5" alignItems="center" justifyContent="center">
      {visible ? children : null}
    </View>
  )
}

function CheckboxItem({
  children,
  checked = false,
  onCheckedChange,
  icon,
  disabled,
}: DropdownMenuCheckboxItemProps) {
  const { setOpen } = useSheetMenu()
  return (
    <Row
      role="checkbox"
      checked={checked}
      disabled={disabled}
      onPress={() => {
        onCheckedChange?.(!checked)
        setOpen(false)
      }}
    >
      <Indicator visible={checked}>
        <CheckIcon size={18} color="$popoverForeground" />
      </Indicator>
      <Icon icon={icon} />
      <Title>{children}</Title>
    </Row>
  )
}

function RadioGroup({ children, value, onValueChange }: DropdownMenuRadioGroupProps) {
  return <RadioContext.Provider value={{ value, onValueChange }}>{children}</RadioContext.Provider>
}

function RadioItem({ children, value, icon, disabled }: DropdownMenuRadioItemProps) {
  const { setOpen } = useSheetMenu()
  const group = useContext(RadioContext)
  const checked = group.value === value
  return (
    <Row
      role="radio"
      checked={checked}
      disabled={disabled}
      onPress={() => {
        group.onValueChange?.(value)
        setOpen(false)
      }}
    >
      <Indicator visible={checked}>
        <View width="$2" height="$2" borderRadius="$full" backgroundColor="$popoverForeground" />
      </Indicator>
      <Icon icon={icon} />
      <Title>{children}</Title>
    </Row>
  )
}

function Label({ children }: DropdownMenuLabelProps) {
  return (
    <Text
      role="heading"
      size="xs"
      weight="semibold"
      tone="muted"
      paddingHorizontal="$3"
      paddingTop="$3"
      paddingBottom="$1"
    >
      {children}
    </Text>
  )
}

function Separator() {
  return <View height={1} backgroundColor="$border" marginVertical="$1" />
}

function Group({ children }: DropdownMenuGroupProps) {
  return <View>{children}</View>
}

export const sheetMenu = {
  Root,
  Content,
  Item,
  CheckboxItem,
  RadioGroup,
  RadioItem,
  Label,
  Separator,
  Group,
}

import type { ReactElement, ReactNode } from 'react'

// Shared by DropdownMenu.tsx (web) and DropdownMenu.native.tsx so both
// platforms expose exactly the same API.

export interface DropdownMenuProps {
  children: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Side of the trigger to open on (web). Default `bottom`. */
  side?: 'top' | 'right' | 'bottom' | 'left'
  /** Alignment along that side (web). Default `start`. */
  align?: 'start' | 'center' | 'end'
}

export interface DropdownMenuTriggerProps {
  /** A single element, usually a Button or IconButton. */
  children: ReactElement
}

export interface DropdownMenuContentProps {
  children: ReactNode
  /** Minimum menu width (web). Default `$48`. */
  minWidth?: '$40' | '$48' | '$56' | '$64'
}

export interface DropdownMenuItemProps {
  children: ReactNode
  /** Leading icon; sized and tinted for you. */
  icon?: ReactNode
  /** Keyboard shortcut hint shown on the right (web only). */
  shortcut?: string
  /** Style as a dangerous action (delete, sign out…). */
  destructive?: boolean
  disabled?: boolean
  /** Called when the item is chosen; the menu then closes. */
  onSelect?: () => void
  /** Text used for type-ahead when `children` is not a string. */
  textValue?: string
}

export interface DropdownMenuCheckboxItemProps extends Omit<
  DropdownMenuItemProps,
  'onSelect' | 'destructive'
> {
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}

export interface DropdownMenuRadioGroupProps {
  children: ReactNode
  value?: string
  onValueChange?: (value: string) => void
}

export interface DropdownMenuRadioItemProps extends Omit<
  DropdownMenuItemProps,
  'onSelect' | 'destructive'
> {
  value: string
}

export interface DropdownMenuLabelProps {
  children: ReactNode
}

export interface DropdownMenuGroupProps {
  children: ReactNode
}

export const textOf = (node: ReactNode, fallback?: string) =>
  fallback ?? (typeof node === 'string' || typeof node === 'number' ? String(node) : undefined)
